<?php
require dirname(__DIR__).'/includes/bootstrap.php';require_permission('dashboard.view');$pdo=db();$campaign=$pdo->query("SELECT * FROM campaigns WHERE status='active' ORDER BY start_date DESC,id DESC LIMIT 1")->fetch();if(!$campaign)$campaign=['id'=>0,'name'=>'No active campaign','start_date'=>date('Y-m-d'),'deadline'=>date('Y-m-d'),'target_count'=>1,'timezone'=>config('app.timezone')];$cid=(int)$campaign['id'];$counted=0;$today=0;if($cid){$q=$pdo->prepare('SELECT COUNT(*) FROM campaign_registrations WHERE campaign_id=? AND counted=1');$q->execute([$cid]);$counted=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT COUNT(*) FROM campaign_registrations WHERE campaign_id=? AND counted=1 AND DATE(CONVERT_TZ(counted_at,"+00:00","+03:00"))=?');$q->execute([$cid,(new DateTimeImmutable('now',new DateTimeZone((string)($campaign['timezone']??'Asia/Qatar'))))->format('Y-m-d')]);$today=(int)$q->fetchColumn();}$progress=campaign_progress($campaign,$counted,$today);$totalDrivers=(int)$pdo->query("SELECT COUNT(*) FROM drivers WHERE status<>'rejected'")->fetchColumn();$pending=(int)$pdo->query("SELECT COUNT(*) FROM tasks WHERE status NOT IN ('completed','cancelled')")->fetchColumn();$overdue=(int)$pdo->query("SELECT COUNT(*) FROM tasks WHERE status NOT IN ('completed','cancelled') AND due_at IS NOT NULL AND due_at<UTC_TIMESTAMP()")->fetchColumn();$completed=(int)$pdo->query("SELECT COUNT(*) FROM tasks WHERE status='completed'")->fetchColumn();$activeEmployees=(int)$pdo->query("SELECT COUNT(*) FROM employees WHERE employment_status='active'")->fetchColumn();json_response(['ok'=>true,'data'=>compact('progress','totalDrivers','pending','overdue','completed','activeEmployees')]);
